import{S as t,o as e,c as n,a9 as l,B as h}from"./chunks/framework.IJ8axLs_.js";const k="/agentsrc/images/claudecode/05-agent-dispatch.svg",p="/agentsrc/images/claudecode/05-teammate-loop.svg",c=JSON.parse('{"title":"Claude Code Agent 系统拆解：四级机制共用一个 Task 底座","description":"","frontmatter":{"title":"Claude Code Agent 系统拆解：四级机制共用一个 Task 底座"},"headers":[],"relativePath":"claudecode/05-agents.md","filePath":"claudecode/05-agents.md","lastUpdated":1790217011000}'),d={name:"claudecode/05-agents.md"},E=Object.assign(d,{setup(r){const i=[{question:"Claude Code 的四级 agent 机制（AgentTool → Teammate → Coordinator → Swarm）的演进逻辑是什么？",options:["每级机制完全独立设计彼此之间不存在演进关系","从一次性派生到常驻协作再到显式编排与多后端团队","从复杂逐步简化功能不断减少以降低使用门槛","全部同时设计仅通过 feature flag 分阶段发布"],correct:1,explanation:"AgentTool 提供一次性子 agent（同步/异步）；Teammate 实现进程内常驻 agent，用 AsyncLocalStorage 隔离上下文；Coordinator 把模型变成专职协调者；Swarm 支持多后端（tmux/iTerm2/in-process）的 agent 团队协作。每级解决上一级无法覆盖的痛点。"},{question:"为什么 Task 接口只保留了 `kill()` 这一个多态方法？",options:["spawn 与 render 从未被多态调用各 Task 各自维护","TypeScript 类型限制接口不可承载多态方法","kill 的实现由基类统一提供各 Task 只补状态字段","其余方法因调用方不满在评审时被集体移除"],correct:0,explanation:"源码注释明确说明：spawn/render 等方法从未被多态调用过（在 #22546 中移除）。每个具体 Task 类型各自维护 spawn 逻辑与状态结构，Task 接口只在需要按类型找到并 kill 时才被用到。这是一次接口收敛。"},{question:"Fork subagent 路径显式继承父 agent 的完整工具数组（常规子 agent 独立装配），原因是什么？",options:["fork 子 agent 不需要工具级别的权限过滤与检查","fork 子 agent 复用父 cache 需保持工具集完全一致","fork 子 agent 缺少独立权限模式无法运行多数工具","fork 路径强制全部 spawn 为同步无需独立工具池"],correct:1,explanation:"如果工具定义的序列化与父 agent 不同，API 请求前缀就会 diverge，prompt cache 在第一个不同的工具处失效。fork 实验的核心目标就是让子 agent 复用父的缓存前缀，因此必须用完全相同的工具集。"},{question:"Teammate 的 isIdle 状态与常规子 agent 的终态有什么本质区别？",options:["两种状态语义相同表示子任务已进入终态","isIdle 非终态可被新 prompt 唤醒回到 running","isIdle 是 running 的子状态表示任务持续运转中","isIdle 表示 teammate 运行中出现不可逆失败"],correct:1,explanation:"子 agent（local_agent）是一次性的，跑完即终态。Teammate 常驻，它的主循环是 prompt → run → idle → wait → prompt，idle 后可通过 mailbox 接收新消息再次运行。这种设计让 Teammate 能维护长期协作关系。"},{question:"同步子 agent 运行中转后台（backgrounding）的触发与实现机制是？",options:["用户按钮或超时触发，主循环用 Promise.race 监听信号","子 agent 检测超时后主动向父 agent 发送转后台请求","所有子 agent 默认后台运行同步只是 UI 展示的假象","模型在派生时预声明同步或异步运行中不可切换"],correct:0,explanation:"backgroundSignal 是一个 Promise，用户显式按后台化按钮或 autoBackgroundMs 超时（gate 控制默认 120 秒）时 resolve。主循环用 Promise.race 监听它与下一条用户消息，信号先到就把同步路径切成异步——子 agent 剩余执行包进 detached 闭包，父 agent 立即拿到 async_launched 返回值。"}];return(o,s)=>{const a=t("Quiz");return e(),n("div",null,[s[0]||(s[0]=l("",160)),h(a,{questions:i})])}}});export{c as __pageData,E as default};
